(function(){AppModule.register({routes:[
{path:"analytics/enterprise",title:"企业经营分析",permission:"analytics.read",render(){return UI.head("企业经营分析","区分生产过程数据、项目完成数据和正式交付数据。",UI.btn("导出报表","export"))+'<div class="grid grid-4">'+UI.metric("正式交付作品","7","审核通过并交付","▶")+UI.metric("交付集数","96","去重后的正式版本","▦")+UI.metric("任务成功率","92.4%","终态任务口径","✓")+UI.metric("实际成本","¥126,480","样例金额，非账单","￥")+'</div><div class="grid grid-2" style="margin-top:16px">'+UI.card("员工交付集数",UI.bars(["林知远","陈可心","王亦宁","周明"],[22,18,16,8]))+UI.card("成本归属口径",'<div class="list"><div class="list-row"><span>员工个人账户实际扣费</span><b>单独统计</b></div><div class="list-row"><span>企业承担 / 报销</span><b>单独统计</b></div><div class="list-row"><span>赠送 / 免费额度</span><b>单独统计</b></div><div class="list-row"><span>失败与重试费用</span><b>保留</b></div></div>')+'</div><div class="notice" style="margin-top:15px">统计样例仅用于展示信息结构。正式指标必须可下钻到项目、集、镜头、任务、模型调用和账单来源；员工移交不覆盖历史贡献。</div>';}},
{path:"analytics/employee",title:"员工产出分析",permission:"analytics.read",render(){const rows=DB.users.map(u=>'<tr><td>'+u.name+'</td><td>'+u.department+'</td><td>'+u.projects+'</td><td>'+u.delivered+'</td><td>'+u.delivered*12+'</td><td>'+UI.tag("演示样例")+'</td></tr>').join("");return UI.head("员工产出分析","按员工查看项目、正式作品、集数、质量、效率和费用承担。")+UI.card("员工产出",UI.table(["员工","部门","项目数","交付作品","交付集数（示例）","口径"],rows));}}
]});})();